package com.certpath.api;
import com.certpath.api.ApiModels.ApiResponse;import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.util.NoSuchElementException;
@RestControllerAdvice public class GlobalExceptionHandler{@ExceptionHandler({IllegalArgumentException.class,MethodArgumentNotValidException.class})ResponseEntity<ApiResponse<Void>> bad(Exception e){return ResponseEntity.badRequest().body(new ApiResponse<>(false,null,e instanceof MethodArgumentNotValidException?"입력값을 확인해 주세요.":e.getMessage()));}@ExceptionHandler(NoSuchElementException.class)ResponseEntity<ApiResponse<Void>> notFound(Exception e){return ResponseEntity.status(404).body(new ApiResponse<>(false,null,e.getMessage()));}@ExceptionHandler(Exception.class)ResponseEntity<ApiResponse<Void>> unknown(Exception e){return ResponseEntity.status(500).body(new ApiResponse<>(false,null,"요청을 처리하지 못했습니다."));}}
